/* Private in-process ETW only: no kernel/global session or cache control. */
#define main original_probe_main
#include "../benchmarks/d3d12_startup.c"
#undef main
#include <evntrace.h>

static const GUID cache_provider={0x2d4ebca6,0xea64,0x453f,{0xa2,0x92,0xae,0x2e,0xa0,0xee,0x51,0x3b}};
static const GUID private_session={0x956dc83e,0x0a98,0x48bc,{0xa9,0xd3,0x64,0xe0,0x39,0x63,0x77,0xd4}};
typedef struct private_properties {
 EVENT_TRACE_PROPERTIES value;wchar_t name[128];wchar_t file[32768];
} private_properties;
int main(int argc,char **argv){
 private_properties *properties=calloc(1,sizeof(*properties));if(!properties)return 2;
 DWORD n=GetEnvironmentVariableW(L"NEXAUI_R01_PRIVATE_TRACE_FILE",properties->file,32768);
 if(!n || n>=32768 || GetFileAttributesW(properties->file)!=INVALID_FILE_ATTRIBUTES){free(properties);return 3;}
 wcscpy_s(properties->name,128,L"NexaUI R01 private shader-cache startup");
 EVENT_TRACE_PROPERTIES *p=&properties->value;
 p->Wnode.BufferSize=sizeof(*properties);p->Wnode.Guid=private_session;
 p->Wnode.ClientContext=1;p->Wnode.Flags=WNODE_FLAG_TRACED_GUID;
 p->BufferSize=64;p->MinimumBuffers=2;p->MaximumBuffers=8;p->MaximumFileSize=16;
 p->LogFileMode=EVENT_TRACE_FILE_MODE_SEQUENTIAL|EVENT_TRACE_PRIVATE_LOGGER_MODE|EVENT_TRACE_PRIVATE_IN_PROC;
 p->LoggerNameOffset=offsetof(private_properties,name);p->LogFileNameOffset=offsetof(private_properties,file);
 TRACEHANDLE trace=0;ULONG start=StartTraceW(&trace,properties->name,p);
 if(start){fprintf(stderr,"ETW {\"start\":%lu,\"enable\":null,\"stop\":null}\n",start);free(properties);return 4;}
 ULONG enable=EnableTraceEx2(trace,&cache_provider,EVENT_CONTROL_CODE_ENABLE_PROVIDER,TRACE_LEVEL_VERBOSE,UINT64_C(0x800000000000000f),0,0,NULL);
 int result=enable?5:original_probe_main(argc,argv);
 ULONG disable=EnableTraceEx2(trace,&cache_provider,EVENT_CONTROL_CODE_DISABLE_PROVIDER,0,0,0,0,NULL);
 ULONG stop=ControlTraceW(trace,properties->name,p,EVENT_TRACE_CONTROL_STOP);
 fprintf(stderr,"ETW {\"start\":%lu,\"enable\":%lu,\"disable\":%lu,\"stop\":%lu,\"events_lost\":%lu,\"buffers_written\":%lu,\"log_buffers_lost\":%lu}\n",start,enable,disable,stop,p->EventsLost,p->BuffersWritten,p->LogBuffersLost);
 free(properties);return result||disable||stop?6:0;
}

#define WIN32_LEAN_AND_MEAN
#define UNICODE
#include <windows.h>
#include <evntrace.h>
#include <evntcons.h>
#include <tdh.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
static const GUID cache_provider={0x2d4ebca6,0xea64,0x453f,{0xa2,0x92,0xae,0x2e,0xa0,0xee,0x51,0x3b}};
static unsigned count,other;
static void string(const char *s){putchar('"');for(;*s;++s){unsigned char c=(unsigned char)*s;
 if(c=='"'||c=='\\')printf("\\%c",c);else if(c<32)printf("\\u%04x",c);else putchar(c);}putchar('"');}
static void wide(const wchar_t *s){char value[4096];if(!s || !WideCharToMultiByte(CP_UTF8,0,s,-1,value,sizeof(value),NULL,NULL))string("");else string(value);}
static void hex(const void *data,ULONG n){const unsigned char *p=data;putchar('"');for(ULONG i=0;i<n;++i)printf("%02x",p[i]);putchar('"');}
static void WINAPI event(PEVENT_RECORD record){
 if(!IsEqualGUID(&record->EventHeader.ProviderId,&cache_provider)){++other;return;}
 EVENT_DESCRIPTOR d=record->EventHeader.EventDescriptor;
 printf("%s{\"id\":%u,\"opcode\":%u,\"task\":%u,\"pid\":%lu,\"tid\":%lu,\"tick\":%lld,\"payload\":",count++?",":"",d.Id,d.Opcode,d.Task,record->EventHeader.ProcessId,record->EventHeader.ThreadId,record->EventHeader.TimeStamp.QuadPart);hex(record->UserData,record->UserDataLength);
 ULONG bytes=0;ULONG status=TdhGetEventInformation(record,0,NULL,NULL,&bytes);
 TRACE_EVENT_INFO *info=bytes && bytes<=131072?malloc(bytes):NULL;
 if(info && status==ERROR_INSUFFICIENT_BUFFER)status=TdhGetEventInformation(record,0,NULL,info,&bytes);
 printf(",\"metadata_error\":%lu,\"task_name\":",status);
 if(!status && info && info->TaskNameOffset<bytes)wide((wchar_t *)((BYTE *)info+info->TaskNameOffset));else string("");
 printf(",\"properties\":[");
 if(!status && info)for(ULONG i=0;i<info->TopLevelPropertyCount;++i){
  EVENT_PROPERTY_INFO property=info->EventPropertyInfoArray[i];wchar_t *name=(wchar_t *)((BYTE *)info+property.NameOffset);
  PROPERTY_DATA_DESCRIPTOR descriptor={(ULONGLONG)(uintptr_t)name,ULONG_MAX,0};ULONG length=0;
  ULONG error=TdhGetPropertySize(record,0,NULL,1,&descriptor,&length);BYTE *value=length && length<=65536?malloc(length):NULL;
  if(!error && value)error=TdhGetProperty(record,0,NULL,1,&descriptor,length,value);
  printf("%s{\"name\":",i?",":"");wide(name);printf(",\"in_type\":%u,\"out_type\":%u,\"error\":%lu,\"raw\":",property.nonStructType.InType,property.nonStructType.OutType,error);hex(value,value&&!error?length:0);putchar('}');free(value);
 }
 puts("]}");free(info);
}
int wmain(int argc,wchar_t **argv){
 if(argc!=2)return 2;EVENT_TRACE_LOGFILEW logfile={0};logfile.LogFileName=argv[1];
 logfile.ProcessTraceMode=PROCESS_TRACE_MODE_EVENT_RECORD|PROCESS_TRACE_MODE_RAW_TIMESTAMP;logfile.EventRecordCallback=event;
 TRACEHANDLE trace=OpenTraceW(&logfile);if(trace==INVALID_PROCESSTRACE_HANDLE){fprintf(stderr,"OpenTrace %lu\n",GetLastError());return 3;}
 printf("{\"frequency\":%lld,\"events\":[\n",logfile.LogfileHeader.PerfFreq.QuadPart);
 ULONG status=ProcessTrace(&trace,1,NULL,NULL);ULONG close=CloseTrace(trace);
 printf("],\"count\":%u,\"other\":%u,\"process_error\":%lu,\"close_error\":%lu}\n",count,other,status,close);
 return status||close?4:0;
}
